import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.DbIb1qZn.js";const u=JSON.parse('{"title":"CLI reference","description":"Every frensense command, flag, output format and exit code.","frontmatter":{"title":"CLI reference","description":"Every frensense command, flag, output format and exit code."},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md"}'),n={name:"guide/cli.md"};function s(r,e,i,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>This page matches <code>frensense --help</code> for version 0.8.0. If your installed version is older or newer, <code>frensense --help</code> is the final word.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>frensense &lt;path&gt;</code></td><td>Scan a file or folder and print findings. Use <code>.</code> for the current folder. With no arguments it prints the help text.</td></tr><tr><td><code>frensense watch [path]</code></td><td>Re-scan when files change and print only new findings.</td></tr><tr><td><code>frensense explain [rule-id]</code></td><td>Explain one rule (CWE, why, fix). With no id, list all rules.</td></tr><tr><td><code>frensense mcp</code></td><td>Run the MCP server for AI agents. See <a href="/guide/mcp">AI agents</a>.</td></tr><tr><td><code>frensense lsp</code></td><td>Run the editor server. See <a href="/guide/lsp">Editors</a>.</td></tr><tr><td><code>frensense bundle &lt;corpus&gt; [out.frc]</code></td><td>Compile labelled examples into a <code>.frc</code> bundle.</td></tr><tr><td><code>frensense bundle info &lt;file.frc&gt;</code></td><td>Show what a bundle contains (<code>--json</code> for machine output).</td></tr><tr><td><code>frensense lint &lt;corpus&gt;</code></td><td>Check corpus examples before they are bundled.</td></tr></tbody></table><p>Everything is in the one binary. There is no separate MCP or LSP package.</p><h3 id="when-a-folder-has-the-same-name-as-a-command" tabindex="-1">When a folder has the same name as a command <a class="header-anchor" href="#when-a-folder-has-the-same-name-as-a-command" aria-label="Permalink to &quot;When a folder has the same name as a command&quot;">​</a></h3><p>A path that exists wins over a subcommand name, so a repository containing a <code>mcp/</code> or <code>watch/</code> folder can still be scanned with the bare word. Each mode has a spelling that cannot be confused:</p><table tabindex="0"><thead><tr><th>To do this</th><th>Use</th></tr></thead><tbody><tr><td>Start the MCP server</td><td><code>frensense --mcp</code></td></tr><tr><td>Watch a path</td><td><code>frensense watch &lt;path&gt;</code> (the path makes it unambiguous)</td></tr><tr><td>Compile a bundle</td><td><code>frensense bundle &lt;corpus&gt; [out.frc]</code></td></tr><tr><td>Lint a corpus</td><td><code>frensense lint &lt;corpus&gt;</code></td></tr><tr><td>List all rules</td><td><code>frensense --list-rules</code></td></tr><tr><td>Explain one rule</td><td><code>frensense --explain-rule &lt;rule-id&gt;</code></td></tr></tbody></table><p><code>frensense lsp</code> is always the server, because editors start it without a terminal and a silent scan there would be a bug, not an ambiguity.</p><h2 id="scan-options" tabindex="-1">Scan options <a class="header-anchor" href="#scan-options" aria-label="Permalink to &quot;Scan options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>-b</code>, <code>--bundle &lt;file&gt;</code></td><td>Load a <code>.frc</code> <a href="/bundles">bundle</a> for this scan. <code>--corpus-bundle</code> is an older spelling of the same flag.</td></tr><tr><td><code>-l</code>, <code>--language &lt;lang&gt;</code></td><td>Scan one language only: <code>c</code>, <code>go</code>, <code>javascript</code>, <code>python</code>, <code>rust</code>, <code>typescript</code>, <code>vue</code>.</td></tr><tr><td><code>-s</code>, <code>--severity &lt;level&gt;</code></td><td>Lowest severity to report: <code>critical</code>, <code>warning</code> or <code>info</code>. Default <code>warning</code>, so <code>info</code> findings are hidden unless you ask.</td></tr><tr><td><code>-p</code>, <code>--profile &lt;name&gt;</code></td><td><code>default</code>, <code>recommended</code> or <code>strict</code>. <code>strict</code> also reports hygiene rules such as function complexity.</td></tr><tr><td><code>--hygiene</code></td><td>Report hygiene rules (for example, function complexity) under any profile.</td></tr><tr><td><code>--max-complexity &lt;n&gt;</code></td><td>Complexity ceiling before a function is reported (default 25).</td></tr><tr><td><code>--diff-only</code></td><td>Report only findings on lines changed since the last git commit. Changed files are still analysed whole, because a change can make an old line reachable.</td></tr></tbody></table><h2 id="output-options" tabindex="-1">Output options <a class="header-anchor" href="#output-options" aria-label="Permalink to &quot;Output options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>-o</code>, <code>--output &lt;file&gt;</code></td><td>Write the report to a file instead of printing it.</td></tr><tr><td><code>-f</code>, <code>--format &lt;fmt&gt;</code></td><td><code>text</code>, <code>json</code>, <code>sarif</code> or <code>github</code>.</td></tr><tr><td><code>--json</code></td><td>One JSON object with an <code>advisories</code> list. Same as <code>--format json</code>.</td></tr><tr><td><code>--sarif</code></td><td>SARIF 2.1.0. Same as <code>--format sarif</code>.</td></tr><tr><td><code>--github</code></td><td>GitHub Actions annotation commands. Same as <code>--format github</code>.</td></tr><tr><td><code>--show-flows</code></td><td>In text output, list each step from source to sink. (JSON and SARIF always include the path.)</td></tr><tr><td><code>--explain</code></td><td>Also list sink arguments that produced no finding and why (printed to stderr).</td></tr><tr><td><code>--explain-json &lt;file&gt;</code></td><td>Write those silent sink arguments to a file as JSON. Implies <code>--explain</code>.</td></tr></tbody></table><h3 id="the-json-report" tabindex="-1">The JSON report <a class="header-anchor" href="#the-json-report" aria-label="Permalink to &quot;The JSON report&quot;">​</a></h3><p><code>--json</code> prints a single JSON object, not one object per line. The fields you will most often use:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>advisory_count</code></td><td>Number of findings.</td></tr><tr><td><code>advisories</code></td><td>The findings. Each has <code>rule_id</code>, <code>severity</code>, <code>title</code>, <code>file_path</code>, <code>line</code>, <code>column</code>, <code>fingerprint</code> and <code>taint_steps</code>.</td></tr><tr><td><code>clean</code></td><td><code>true</code> when there are no findings.</td></tr><tr><td><code>analysis_incomplete</code></td><td>Reasons the scan may have missed things (unsupported or partly parsed files, safety limits). Check this before you trust a clean result.</td></tr><tr><td><code>schema_version</code></td><td>Version of this report format.</td></tr></tbody></table><h2 id="gating-options" tabindex="-1">Gating options <a class="header-anchor" href="#gating-options" aria-label="Permalink to &quot;Gating options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--strict</code></td><td>Exit 1 if there is <strong>any</strong> finding.</td></tr><tr><td><code>--emit-baseline &lt;file&gt;</code></td><td>Save the current findings as a baseline.</td></tr><tr><td><code>--compare-baseline &lt;file&gt;</code></td><td>Exit 1 only if there are findings that are not in the baseline.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Do not combine <code>--strict</code> with <code>--compare-baseline</code></p><p><code>--strict</code> fails on any finding, including ones already in the baseline, so the pair fails every run. Use <code>--compare-baseline</code> on its own for a regression gate. See <a href="/guide/github-actions">CI and agent gating</a>.</p></div><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><code>0</code></td><td>The scan finished. Findings do not change this unless you ask for it.</td></tr><tr><td><code>1</code></td><td><code>--strict</code> and at least one finding; or <code>--compare-baseline</code> found a new finding; or an error such as an unreadable bundle file.</td></tr><tr><td><code>2</code></td><td>The command line was wrong (unknown flag, invalid severity, and so on).</td></tr></tbody></table><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>FRENSENSE_CORPUS_BUNDLE</code></td><td>Default <code>.frc</code> bundle for the MCP and LSP servers. The CLI scan uses <code>-b</code> instead.</td></tr></tbody></table><p>A file named <code>frensense-corpus.frc</code> in the folder being scanned is loaded automatically when no <code>-b</code> is given.</p><h2 id="explaining-a-rule" tabindex="-1">Explaining a rule <a class="header-anchor" href="#explaining-a-rule" aria-label="Permalink to &quot;Explaining a rule&quot;">​</a></h2><p>Every finding carries a stable rule id (<code>taint.sql-injection</code>, <code>check.weak-hash</code>, ...). <code>frensense explain &lt;rule-id&gt;</code> prints what it means:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ frensense explain taint.path-traversal</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">taint.path-traversal  Path traversal</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  CWE:  CWE-22  https://cwe.mitre.org/data/definitions/22.html</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  why:  Attacker-supplied path segments can reach files outside the intended directory.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  fix:  Resolve the path, then check it stays inside the allowed base directory; prefer fixed names.</span></span></code></pre></div><p>Rules that came from a bundle describe themselves from the bundle&#39;s data. Pass <code>-b</code> to explain or list them:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ frensense explain policy.redirect-challenge -b learned.frc</span></span></code></pre></div><h2 id="version-and-identity" tabindex="-1">Version and identity <a class="header-anchor" href="#version-and-identity" aria-label="Permalink to &quot;Version and identity&quot;">​</a></h2><p><code>frensense --version</code> prints the version. <code>frensense --version --json</code> also prints the bundle format the binary reads and the size of the built-in knowledge pack.</p><h2 id="corpus-commands" tabindex="-1">Corpus commands <a class="header-anchor" href="#corpus-commands" aria-label="Permalink to &quot;Corpus commands&quot;">​</a></h2><p><code>frensense lint &lt;corpus&gt;</code> takes <code>--strict</code>, <code>--json</code>, <code>--coverage</code>, <code>--no-gate</code>, <code>--classes &lt;file&gt;</code>, <code>--advisories &lt;file&gt;</code>, <code>--require-heldout</code> and <code>--dup-threshold &lt;0..1&gt;</code>. It exits 1 when it finds an error. The <a href="/corpus/authoring">authoring guide</a> explains what each check means.</p>`,33)])])}const f=t(n,[["render",s]]);export{u as __pageData,f as default};
